    s = input().strip()
    t_str = input().strip()

    # Check if character counts match
    if sorted(s) != sorted(t_str):
        print(-1)
        continue

    # If already equal
    if s == t_str:
        print(0)
        continue

    # Try rotating the entire string
    if sorted(s) == sorted(t_str) and s == t_str:
        print(0)
        continue

    # Try rotating a substring to see if we can match
    matched = False
    for l in range(n):
        for r in range(l, n):
            # Rotate substring [l, r]
            rotated = list(s)
            # Rotate clockwise once
            rotated[l], rotated[l+1:r+1] = rotated[r], rotated[l:r]
            if ''.join(rotated) == t_str:
                matched = True
                break
        if matched:
            break

    if matched:
        print(1)
    else:
        print(2)
