import sys

def parse_employees(s):
    """Parse the input string into a list of employees and their subordinates"""
    employees = []
    i = 0
    while i < len(s):
        # Find the name
        j = i
        while j < len(s) and s[j] not in ":." and s[j] != ",":
            j += 1
        name = s[i:j]
        i = j

        # Find subordinates
        subordinates = []
        if i < len(s) and s[i] == ":":
            i += 1
            while i < len(s) and s[i] != ".":
                if s[i] == ",":
                    i += 1
                else:
                    # Find the end of this subordinate's description
                    k = i
                    while k < len(s) and s[k] not in ".":
                        k += 1
                    subordinates.append(s[i:k])
                    i = k
            i += 1  # Skip the dot
        else:
            # No subordinates, skip the dot
            i += 1

        employees.append((name, subordinates))
    return employees

def count_uncomfortable_pairs(employees):
    """Count uncomfortable pairs in the corporation"""
    # Build a mapping from name to list of employees with that name
    name_to_employees = {}
    for name, subordinates in employees:
        if name not in name_to_employees:
            name_to_employees[name] = []
        name_to_employees[name].append((name, subordinates))

    # Count uncomfortable pairs
    count = 0

    # For each employee, traverse their subtree
    for name, subordinates in employees:
        # Traverse all subordinates (direct and indirect)
        stack = subordinates.copy()
        while stack:
            sub_name, sub_subordinates = stack.pop()
            # Check if this subordinate has the same name
            if sub_name == name:
                count += 1
            # Add all of this subordinate's subordinates
            stack.extend(sub_subordinates)

    return count

def main():
    s = sys.stdin.read().strip()
    employees = parse_employees(s)
    print(count_uncomfortable_pairs(employees))

if __name__ == "__main__":
    main()
"}

