    for i in range(n):
        if i == 0:
            a[i] = m[i]
        else:
            a[i] = min(m[i], a[i-1])

    # Second pass: ensure we don't have a valley
    for i in range(n-1):
        if a[i] < a[i+1]:
            a[i] = a[i+1]

    print(' '.join(map(str, a)))

if __name__ == '__main__':
