def solve():
    data = sys.stdin.read().strip().split()
    n, *rest = map(int, data)
    m = rest[:n]

    if n == 0:
        return

    a = [0] * n

    # Left to right: maximum possible height but not greater than previous
    a[0] = m[0]
    for i in range(1, n):
        a[i] = min(a[i-1], m[i])

    # Right to left: ensure no valley by increasing if needed
    for i in range(n-1, 0, -1):
        a[i-1] = min(a[i], a[i-1])

    print(' '.join(map(str, a)))

