def is_valid(grid, n, m, k):
    ones = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 1]
    if not ones:
        return False

    # Try each position as a potential starting position
    for start_i, start_j in ones:
        # BFS to explore all positions reachable by moving k units
        from collections import deque
        queue = deque([(start_i, start_j, 0)])  # (i, j, steps_from_start)
        visited = set([(start_i, start_j)])

        while queue:
            i, j, steps = queue.popleft()

            # Try all four directions
            for di, dj in [(k, 0), (-k, 0), (0, k), (0, -k)]:
                ni, nj = i + di, j + dj

                # Check if the new position is valid
                if 0 <= ni < n and 0 <= nj < m:
                    # Check if we've visited this exact position before with a different step count
                    if (ni, nj) in visited:
                        # Revisiting the same position means we've revisited a segment
                        return False

                    # Check if this position has value 1
                    if grid[ni][nj] == 1:
                        visited.add((ni, nj))
                        queue.append((ni, nj, steps + 1))

    return True

n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(list(map(int, input().split())))

# Try all possible k values
possible_ks = []
k_max = max(n, m)  # The maximum k can't exceed the grid size
for k in range(2, k_max + 1):
    if is_valid(grid, n, m, k):
        possible_ks.append(k)

if possible_ks:
    print(' '.join(map(str, possible_ks)))
else:
    print(-1)
"}

