def to_base_k(n, k, max_number=None):
    """Convert a number n to base k. If max_number is given, use it to determine digits"""
    if n == 0:
        return "0"

    # The number of digits in base k is log_k(max_number) + 1 (ceiling)
    if max_number is None:
        # We can use the number of digits for k
        digits_needed = 0
        temp = n
        while temp > 0:
            temp = temp // k
            digits_needed += 1
