        digits = []
        while max_number > 0:
            digits.append(str(max_number % k))
            max_number //= k
        digits = ''.join(reversed(digits))
        return ''.join([str((n // (k**len(digits) - i)) % k) for i in range(len(digits), 0, -1)])

print(to_base_k(1, k, max_number=(k-1)**2))
