import sys

def count_set_bits(x):
    """Count the number of set bits in x"""
    count = 0
    while x:
        count += x & 1
        x >>= 1
    return count

def solve(s, x):
    """Solve the XOR Equation problem"""
    if s < x or (s - x) % 2 != 0:
        return 0

    # Count the number of set bits in x
    b = count_set_bits(x)

    # If s > x, we need to subtract the two invalid cases where a = 0 or b = 0
    if s > x:
        return (1 << b) - 2
    else:
        # If s == x, we also need to subtract the two invalid cases
        return (1 << b) - 2


if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)

    s = int(data[0])
    x = int(data[1])

    result = solve(s, x)
    print(result)
"}

