def factorize(n):
    """Return the prime factorization of n as a dictionary."""
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def get_signature(n, k):
    """Return the signature of n modulo k."""
    factors = factorize(n)
    signature = {}
    for prime, exp in factors.items():
        signature[prime] = exp % k
    return signature

def main():
    import sys
    input = sys.stdin.read().strip().split()
    if not input:
        return

    n = int(input[0])
    k = int(input[1])
    a = list(map(int, input[2:2+n]))

    # Count occurrences of each signature
    from collections import defaultdict
    signature_count = defaultdict(int)
    for num in a:
        sig = get_signature(num, k)
        # To make it hashable, convert to a tuple of sorted items
        signature_tuple = tuple(sorted(sig.items()))
        signature_count[signature_tuple] += 1

    # Count valid pairs
    result = 0
    for sig1, count1 in signature_count.items():
        for sig2, count2 in signature_count.items():
            # Check if sig1 + sig2 is all zeros modulo k
            valid = True
            for prime1, exp1 in sig1.items():
                if prime1 not in sig2:
