import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        graph[u].append(v)
        graph[v].append(u)

    # Find longest path using DFS
    max_length = 0

    def dfs(node, parent, current_length):
        nonlocal max_length
        max_length = max(max_length, current_length)

        for neighbor in graph[node]:
            if neighbor != parent:
                dfs(neighbor, node, current_length + 1)

    for i in range(1, n + 1):
        dfs(i, -1, 1)

    print(max_length)

if __name__ == "__main__":
    solve()
"}

