def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    # Count occurrences of each character
    count = {}
    for ch in s:
        count[ch] = count.get(ch, 0) + 1

    # For strings of length 1
    max_count = max(count.values())

    # For strings of length 2
    # Count pairs (i, j) where s[i] = first char, s[j] = second char, i < j
    # The number of such pairs is count[first] * count[second] if first != second
    # For first == second, it's C(count[first], 2)

    for first in count:
        for second in count:
            if first != second:
                current_count = count[first] * count[second]
            else:
                current_count = count[first] * (count[first] - 1) // 2

            if current_count > max_count:
                max_count = current_count

    print(max_count)

if __name__ == "__main__":
