def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    x1 = int(next(it))
    x2 = int(next(it))

    lines = []
    for _ in range(n):
        k = int(next(it))
        b = int(next(it))
        lines.append((k, b))

    # Check all pairs of lines
    for i in range(n):
        for j in range(i + 1, n):
            k1, b1 = lines[i]
            k2, b2 = lines[j]

            if k1 == k2:
                continue

            # Check if intersection x = (b2 - b1) / (k1 - k2) is inside (x1, x2)
            # This is equivalent to (k1 - k2) * x1 < (b2 - b1) < (k1 - k2) * x2
            if (b2 - b1) > (k1 - k2) * x1 and (b2 - b1) < (k1 - k2) * x2:
                print("YES")
                return

            # In the other case, we need to reverse the inequalities
            # because (k1 - k2) < 0 means denominator is negative
            if (k1 - k2) < 0:
                # x1 < (b2 - b1) > (k1 - k2) * x2 (but k1 - k2 < 0 means it's actually x1 < (b2 - b1) > something negative)
