import sys

def is_lucky(n):
    while n > 0:
        if n % 10 not in {4, 7}:
            return False
        n //= 10
    return True

def count_lucky_in_interval(a, b):
    # Count lucky numbers in [a, b]
    count = 0
    for i in range(a, b + 1):
        if is_lucky(i):
            count += 1
    return count

def brute_force(pl, pr, vl, vr, k):
    lucky_numbers = set()
    for i in range(1, 10**9 + 1):
        if is_lucky(i):
            lucky_numbers.add(i)
        if i > 10**9 + 1:
            break

    total = 0
    count = 0

    for p in range(pl, pr + 1):
        for v in range(vl, vr + 1):
            a = min(p, v)
            b = max(p, v)
            lucky_count = count_lucky_in_interval(a, b)
            if lucky_count == k:
                count += 1
            total += 1

    return count / total

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
