def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, p, *rest = map(int, data)

    probs = []

    while len(probs) < n:
        l, r = rest[2*len(probs)], rest[2*len(probs)+1]
        probs.append((r // p - (l - 1) // p) / (r - l + 1))

    expected = 0
    for i in range(n):
        j = (i + 1) % n
        pi, pj = probs[i], probs[j]
        # 2000 is money for each shark, total 2000*P
        expected += 2000 * (pi + pj - pi * pj)

    # Just print
    if expected.is_integer():
        print(f"{expected:.10f}")
    else:
        print(f"{expected:.15f}")

if __name__ == "__main__":
    solve()
