    fret_options = []
    for note in b:
        options = []
        for string_val in a:
            if string_val <= note - 1:
                fret = note - string_val
                options.append(fret)
        fret_options.append(options)

    # Flatten all fret options and sort
    all_frets = []
    for options in fret_options:
        all_frets.extend(options)

    # Sort all frets
    all_frets.sort()

    # Use a sliding window to find minimum range
    min_range = float('inf')

    for i in range(len(all_frets) - n + 1):
        current_min = all_frets[i]
        current_max = all_frets[i + n - 1]

        # Check if this window contains at least one fret from each note
        note_coverage = [False] * n

        for j in range(i, i + n):
            for k, frets in enumerate(fret_options):
                if all_frets[j] in frets:
                    note_coverage[k] = True
                    break

        if all(note_coverage):
            min_range = min(min_range, current_max - current_min)

    print(min_range)

