    w = int(data[1])

    r = list(map(int, data[2:2+h]))
    c = list(map(int, data[2+h:2+h+w]))

    # Create grid
    grid = [[0 for _ in range(w)] for _ in range(h)]

    for i in range(h):
        for j in range(w):
            # Apply row constraint
            if r[i] > 0:
                if j <= r[i]:
                    grid[i][j] = 1  # full
                elif j == r[i] + 1:
                    grid[i][j] = 0  # empty (if r_i < w)

    for j in range(w):
        for i in range(h):
            # Apply column constraint
            if c[j] > 0:
                if i <= c[j]:
                    grid[i][j] = 1  # full
                elif i == c[j] + 1:
                    grid[i][j] = 0  # empty (if c_j < h)

    # Count unconstrained cells
    unconstrained = 0
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0:
                # Check if cell is constrained by row
                row_full = (r[i] > 0) and (j <= r[i])
                row_empty = (r[i] > 0) and (j == r[i] + 1)

                # Check if cell is constrained by column
                col_full = (c[j] > 0) and (i <= c[j])
                col_empty = (c[j] > 0) and (i == c[j] + 1)

