import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    # row_last[i] = (time, color) for last operation on row i
    row_last = [(0, 0)] * (n + 1)
    # col_last[j] = (time, color) for last operation on column j
    col_last = [(0, 0)] * (m + 1)

    for time in range(1, k + 1):
        typ = int(next(it))
        idx = int(next(it))
        col = int(next(it))

        if typ == 1:
            row_last[idx] = (time, col)
        else:
            col_last[idx] = (time, col)

    # Print result
    out_lines = []
    for i in range(1, n + 1):
        line = []
        for j in range(1, m + 1):
            row_time, row_color = row_last[i]
            col_time, col_color = col_last[j]

            if row_time > col_time:
                line.append(str(row_color))
            elif col_time > row_time:
                line.append(str(col_color))
            else:
                line.append('0')
        out_lines.append(' '.join(line))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
