    while n > 0:
        if n % 10 not in {4, 7}:
            return False
        n //= 10
    return True

# Generate all lucky numbers up to a given limit
# This is a breadth-first search approach
# We start with 4 and 7 and generate numbers by appending 4 and 7 to the right
# We stop when the number exceeds the limit

def generate_lucky_numbers(limit):
    lucky = []
    from collections import deque
    queue = deque()
    queue.extend([4, 7])

    while queue:
        num = queue.popleft()
        if num <= limit:
            lucky.append(num)
            queue.append(num * 10 + 4)
            queue.append(num * 10 + 7)
        else:
            continue
    return sorted(lucky)

# Solve the problem
def solve(pl, pr, vl, vr, k):
    # Generate all lucky numbers up to max(pr, vr)
    max_val = max(pr, vr)
    lucky_numbers = generate_lucky_numbers(max_val)

    # Count how many (p, v) pairs result in exactly k lucky numbers in [min(v, p), max(v, p)]
    # Instead of brute force, we can calculate this using binary search
    # The interval [min(v, p), max(v, p)] contains exactly k lucky numbers
    # This means we need to find pairs (p, v) such that the count of lucky numbers in [a, b] is k

    # First, we need to find all lucky numbers in the range [1, max_val]
    # Then, we need to consider which lucky number combinations give us exactly k

    # Calculate total pairs
    total_pairs = (pr - pl + 1) * (vr - vl + 1)

    # Calculate valid pairs
    valid_pairs = 0

    # Case 1: p <= v
    # We need count of lucky numbers in [p, v] to be exactly k
    # Find all p in [pl, pr] and v in [pl, vr] such that lucky_count[v] - lucky_count[p-1] == k

    # Precompute prefix sums of lucky numbers
    prefix_sum = [0]
    for num in lucky_numbers:
