    def count_lucky_between(a, b):
        # Find first lucky number >= a
        low, high = 0, len(lucky_numbers) - 1
        while low <= high:
            mid = (low + high) // 2
            if lucky_numbers[mid] >= a:
                high = mid - 1
            else:
                low = mid + 1
        lower_idx = low

