        upper_idx = low

        return max(0, upper_idx - lower_idx)

    for v in range(vl, vr + 1):
        for p in range(pl, v + 1):
            # Count lucky numbers in [p, v]
            if count_lucky_between(p, v) == k:
                valid_pairs += 1

    for v in range(vl, vr + 1):
