import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # Count single characters
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1

    # Count pairs of the form (c1, c2)
    pair_freq = {}  # (c1, c2): count

    # For each possible length of subsequence (at least 2)
    # Length 2 (2 indices): i < j
    # For length 3 (3 indices): i < k < j
    # For length 4 (4 indices): i < k1 < k2 < j
    # etc.

    # Start with length 2
    for i in range(n):
        for j in range(i + 1, n):
            # (i, j) is a subsequence of length 2
            pair_freq[(s[i], s[j])] = pair_freq.get((s[i], s[j]), 0) + 1

    # Length 3
    for i in range(n):
        for j in range(i + 2, n):
            for k in range(i + 1, j):
                # (i, k, j) is an arithmetic progression
                # Subsequence is (s[i], s[k], s[j])
                if k - i == j - k:
                    pair_freq[(s[i], s[k], s[j])] = pair_freq.get((s[i], s[k], s[j]), 0) + 1

    # Length 4 (and longer)
    for i in range(n):
        for j in range(i + 3, n):
            if (j - i) % 2 != 0:  # need at least one middle position with same parity
                # i < i1 < i2 < j
                # i1 and i2 must satisfy arithmetic progression
                # i1 - i == i2 - i1 == j - i2
                # i1 = i + d, i2 = i + 2d, j = i + 3d
                i1 = (2*i + j + (j - i) % 1) // 3
