def parse_structure(s):
    # Split by commas to get each employee description
    descriptions = s.split(',')

    # Build a dictionary to map names to their subordinates
    hierarchy = {}

    for desc in descriptions:
        if ':' in desc:
            # Format: name:subordinates.
            name_part, subordinates_part = desc.split(':', 1)
            subordinates = subordinates_part.rstrip('.')
        else:
            # Format: name.
            name_part = desc.rstrip('.')
            subordinates = []

        hierarchy[name_part] = subordinates

    return hierarchy

def count_uncomfortable_pairs(hierarchy):
    # Count uncomfortable pairs
    count = 0

    # For each employee, traverse their subtree
    for name, subordinates in hierarchy.items():
        # Count how many employees with the same name are in this subtree
        # We need to count all descendants (including those in subordinates' subtrees)

        # Traverse subordinates
        for subordinate in subordinates:
            if subordinate in hierarchy:
                # Add the count from this subordinate's subtree
                count += count_uncomfortable_pairs(hierarchy, subordinate)

        # Count the current employee (name itself)
        count += 1

    return count

def count_uncomfortable_pairs_recursive(hierarchy, name):
    # Count how many employees with name 'name' are in this subtree
    count = 0

    if name in hierarchy:
        count += 1  # Count the current employee

        for subordinate in hierarchy[name]:
            if subordinate in hierarchy:
                count += count_uncomfortable_pairs_recursive(hierarchy, subordinate)

