        return False
    sqrt_n = int(math.isqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True

def is_prime_power(n):
    """Check if n is a prime power (p^k where p is prime and k >= 2)."""
    if n < 2:
        return False

