        p = 89
    elif n % 97 == 0:
        p = 97
    else:
        # Try dividing by odd numbers starting from 3
        for i in range(3, int(math.isqrt(n)) + 1, 2):
            if n % i == 0:
                p = i
                break
        else:
            # n is prime
            return False

    # Check if n is a power of p
    while n % p == 0:
        n //= p
    return n == 1

