def find_entrance(n, queues):
    """Find the entrance through which Allen will enter the fan zone."""

    # Find the entrance where the queue decreases the fastest
    # Allen enters through entrance i if a_i - (i-1) is minimized (and non-negative)

    min_value = float('inf')
    answer = -1

    for i in range(n):
        # a_i - (i-1) represents how many minutes before entrance i empties
        # if a_i < i-1, the queue has already emptied
        value = queues[i] - i  # i-1 in 0-indexed is just i

        if value >= 0:
            if value < min_value:
                min_value = value
                answer = i + 1  # Convert to 1-indexed
            elif value == min_value:
                # If tied, choose the one with smaller original queue
                if queues[i] < queues[answer-1]:
                    answer = i + 1

    return answer

