def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

def permutation_rank(p):
    n = len(p)
    rank = 0
    used = [False] * n
    for i in range(n):
        count = 0
        for j in range(n):
            if not used[j] and p[i] > j:
                count += 1
        rank += count * factorial(n - 1 - i)
        used[p[i]] = True
    return rank

def permutation_at_position(n, pos):
    used = [False] * n
    result = [0] * n
    for i in range(n):
        for j in range(n):
            if not used[j]:
                if pos == 0:
                    result[i] = j
                    used[j] = True
                    break
                pos -= 1
    return result

