def compute_lps(s):
    n = len(s)
    lps = [0] * n
    length = 0  # length of the previous longest prefix suffix

    for i in range(1, n):
        while length > 0 and s[i] != s[length]:
            length = lps[length - 1]

        if s[i] == s[length]:
            length += 1
            lps[i] = length
        else:
            lps[i] = 0

    return lps

def find_password(s):
    n = len(s)
    if n == 0:
        return "Just a legend"

    lps = compute_lps(s)
    longest = lps[-1]

    # Check if the longest prefix/suffix appears in the middle
    if longest == 0:
        return "Just a legend"

    # Check if the prefix of length 'longest' appears somewhere in the middle
    # We look at the position before the end of the string
    # If lps[n - longest - 1] >= longest, then the prefix appears in the middle
    if lps[n - longest - 1] >= longest:
        return s[:longest]

    # If not, check shorter prefixes
    for i in range(longest - 1, 0, -1):
        if lps[n - i - 1] >= i:
            return s[:i]

    return "Just a legend"

# Read input and output result
