import sys

def compute_v(sequence, n):
    """Compute the value v after n iterations of alternating OR and XOR operations."""
    current = sequence.copy()
    for i in range(1, n + 1):
        if i % 2 == 1:
            # OR operation
            next_seq = []
            for j in range(0, len(current), 2):
                next_seq.append(current[j] | current[j + 1])
            current = next_seq
        else:
            # XOR operation
            next_seq = []
            for j in range(0, len(current), 2):
                next_seq.append(current[j] ^ current[j + 1])
            current = next_seq
    return current[0]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    sequence = []
    for _ in range(2 * n):
        sequence.append(int(next(it)))

    results = []
    for _ in range(m):
        p = int(next(it)) - 1  # 0-indexed
        b = int(next(it))
        sequence[p] = b
        results.append(str(compute_v(sequence, n)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()
