    n = int(next(it))

    # Build friendship graph
    friends = [[] for _ in range(n + 1)]
    k = int(next(it))
    for _ in range(k):
        u = int(next(it))
        v = int(next(it))
        friends[u].append(v)
        friends[v].append(u)

    # Find connected components using DFS
    visited = [False] * (n + 1)
    components = []

    def dfs(node):
        stack = [node]
        visited[node] = True
        component = [node]

        while stack:
            current = stack.pop()
            for neighbor in friends[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    component.append(neighbor)
                    stack.append(neighbor)

        return component

    for i in range(1, n + 1):
        if not visited[i]:
            component = dfs(i)
            components.append(component)

    # Check for dislikes in each component
    max_size = 0
    m = int(next(it))
    dislikes = set()
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        dislikes.add((u, v))
        dislikes.add((v, u))

    for component in components:
        valid = True
        for i in range(len(component)):
            for j in range(i + 1, len(component)):
                if (component[i], component[j]) in dislikes:
                    valid = False
                    break
            if not valid:
