    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(n)]

    # Segment tree for range updates and point queries
    class SegmentTree:
        def __init__(self, size, initial_value):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.size = size
            self.tree = [initial_value] * (2 * self.n)
            self.lazy = [0] * (2 * self.n)

        def push(self, node, l, r):
            if self.lazy[node] != 0:
                # Propagate to children
                self.tree[2*node] += self.lazy[node]
                self.lazy[2*node] += self.lazy[node]
                self.tree[2*node+1] += self.lazy[node]
                self.lazy[2*node+1] += self.lazy[node]
                # Clear lazy
                self.lazy[node] = 0

        def update_range(self, a, b, val, node=1, l=0, r=None):
            if r is None:
                r = self.n - 1

            if a > r or b < l:
                return

            if a <= l and r <= b:
                self.tree[node] += val
                self.lazy[node] += val
                return

            self.push(node, l, r)
            mid = (l + r) // 2
            self.update_range(a, b, val, 2*node, l, mid)
            self.update_range(a, b, val, 2*node+1, mid+1, r)
            self.tree[node] = self.tree[2*node] + self.tree[2*node+1]

        def query_point(self, idx, node=1, l=0, r=None):
            if r is None:
                r = self.n - 1

            if l == r:
                return self.tree[node]

            self.push(node, l, r)
            mid = (l + r) // 2
            if idx <= mid:
                return self.query_point(idx, 2*node, l, mid)
            else:
                return self.query_point(idx, 2*node+1, mid+1, r)

    # Build segment tree with initial values from array b
    seg_tree = SegmentTree(n, 0)
    for i in range(n):
        seg_tree.update_range(i, i, b[i])

