def factorial(n):
    """Compute factorial of n"""
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def get_rank(permutation, n):
    """Get lexicographical rank of a permutation"""
    used = [False] * n
    rank = 0
    for i in range(n):
        current = permutation[i]
        used[current] = True
        count = 0
        for j in range(n):
            if not used[j] and j < current:
                count += 1
        rank += count * factorial(n - i - 1)
    return rank

def get_permutation(rank, n):
    """Get permutation at a given rank"""
    used = [False] * n
    permutation = [0] * n
    for i in range(n):
        for j in range(n):
            if not used[j]:
                # How many permutations start with this prefix?
                count = 0
                for k in range(n):
                    if not used[k] and k < j:
                        count += 1
                if rank < count * factorial(n - i - 1):
                    permutation[i] = j
                    used[j] = True
                    break
                else:
                    rank -= count * factorial(n - i - 1)
    return permutation

