def count_composite(L, R):
    """Count composite numbers in [L, R]"""
    if R < 4:
        return 0

    # Use Sieve of Eratosthenes to find all primes up to sqrt(10^18)
    max_limit = int(math.isqrt(10 ** 18))
    is_prime = [True] * (max_limit + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(math.isqrt(max_limit)) + 1):
        if is_prime[i]:
            for j in range(i * i, max_limit + 1, i):
                is_prime[j] = False

    # Count numbers in [L, R]
    count = 0
    for x in range(L, R + 1):
        if not is_prime[x] and x > 1:
            count += 1

    return count

