import sys

def solve(a):
    n = len(a)

    # dp[i][j] is a set of strings representing distinct results for substring a[i:j]
    dp = [[set() for _ in range(n)] for _ in range(n)]

    # Base case: single digit
    for i in range(n):
        dp[i][i].add(a[i])

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Try merging the first two digits if they sum to 9
            if int(a[i]) + int(a[i+1]) == 9:
                for s in dp[i+2][j]:
                    new_s = '9' + s
                    dp[i][j].add(new_s)

            # Try not merging the first two digits
            for s1 in dp[i][i+1]:
                for s2 in dp[i+2][j]:
                    dp[i][j].add(s1 + s2)

    # The answer is the size of the set for the whole string
    return len(dp[0][n-1])

a = sys.stdin.readline().strip()
print(solve(a))
