import sys

# This problem is about merging adjacent digits that sum to 9
# We need to count how many distinct final numbers we can get

def solve(a):
    # We use dynamic programming where dp[i][j] is a set of strings that can be formed
    # by merging the substring from index i to j (inclusive)
    n = len(a)
    dp = [[set() for _ in range(n)] for _ in range(n)]

    # Base case: single digit
    for i in range(n):
        dp[i][i].add(a[i])

    # Build up the solution for all lengths
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Try merging digits at positions i and i+1 if they sum to 9
            if int(a[i]) + int(a[i+1]) == 9:
                for s in dp[i+2][j]:
                    dp[i][j].add('9' + s)

            # Try not merging i and i+1, then combine with the rest
            for s1 in dp[i][i+1]:
                for s2 in dp[i+2][j]:
                    dp[i][j].add(s1 + s2)

    return len(dp[0][n-1])

# Get the input
a = sys.stdin.readline().strip()

# Print the solution
result = solve(a)
