def solve():
    import sys
    input = sys.stdin.read().strip().split()
    data = iter(input)

    n = int(next(data))
    m = int(next(data))

    c = [int(next(data)) for _ in range(n)]

    edges = []
    for _ in range(m):
        u = int(next(data)) - 1
        v = int(next(data)) - 1
        edges.append((u, v))

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n)]
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    # Build tree iteratively
    parent = [-1] * n
    stack = [(0, False)]
    visited = [False] * n

    while stack:
        v, processed = stack.pop()
        if processed:
            # Process children
            pass
        else:
            if visited[v]:
                continue
            visited[v] = True
            stack.append((v, True))
            # Push children
            children = []
            for u, idx in adj[v]:
                if u != parent[v]:
                    children.append((u, idx))
                    parent[u] = v
            for u, idx in reversed(children):
                stack.append((u, False))

    # Assign weights iteratively
    weight = [0] * m

    # Use post-order traversal
    post_order = []
    stack = [(0, False)]
    while stack:
        v, processed = stack.pop()
        if not processed:
            stack.append((v, True))
            # Push children (excluding parent)
            children = []
            for u, idx in adj[v]:
                if u != parent[v]:
                    children.append((u, idx))
            for u, idx in reversed(children):
                stack.append((u, False))
        else:
            post_order.append(v)

    # Assign weights bottom-up
    for v in post_order:
        # Sum of weights on edges from v to its children (excluding edge to parent)
        sum_child_weights = 0
        for u, idx in adj[v]:
            if u != parent[v]:
                sum_child_weights += weight[idx]

        # Weight on edge from v to parent
        if parent[v] != -1:
            # Find the edge between v and parent[v]
            for u, idx in adj[v]:
                if u == parent[v]:
                    weight_idx = idx
                    break
            weight[weight_idx] = c[v] - sum_child_weights

    # Check all vertices
    for v in range(n):
        total = sum(weight[i] for u, i in adj[v])
        if abs(total - c[v]) > 1e-9:
            print("NO")
            return

    print("YES")
    for w in weight:
        print(w)

