import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        x_list = [int(next(it)) for _ in range(m)]

        # Compute prefix sums circularly
        prefix_sums = [0] * (n + 1)
        for i in range(n):
            prefix_sums[i + 1] = prefix_sums[i] + a[i]

        total_sum = prefix_sums[n]
        max_prefix = max(prefix_sums[1:])

        # For each query
        res = []
        for x in x_list:
            if total_sum <= 0:
                # Can't go around, only check prefixes
                if x > max_prefix:
                    res.append("-1")
                else:
                    for i in range(1, n + 1):
                        if prefix_sums[i] >= x:
                            res.append(str(i - 1))
                            break
            else:
                # total_sum > 0
                ans = None
                for i in range(1, n + 1):
                    if prefix_sums[i] >= x:
                        ans = i - 1
                        break
                if ans is not None:
                    res.append(str(ans))
                else:
                    # Need to go around at least once
                    # Find the minimum (i + ceil((x - prefix_sums[i])/total_sum) * n)
                    min_steps = float('inf')
                    for i in range(1, n + 1):
                        # prefix_sums[i] < x
                        s = x - prefix_sums[i]
                        k = (s + total_sum - 1) // total_sum  # ceil division
                        steps = i + k * n
                        if steps < min_steps:
                            min_steps = steps
                    res.append(str(min_steps - 1))  # wait, min_steps is total steps, need to check

        print(' '.join(res))

if __name__ == '__main__':
    solve()
