import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    b = []
    for _ in range(n):
        b.append(int(data[idx])); idx += 1

    g = []
    for _ in range(m):
        g.append(int(data[idx])); idx += 1

    impossible = False
    for boy in b:
        if all(gj < boy for gj in g):
            impossible = True
            break

    if impossible:
        print(-1)
        return

    for girl in g:
        if all(bi > girl for bi in b):
            impossible = True
            break

    if impossible:
        print(-1)
        return

    if max(b) > min(g):
        print(-1)
    else:
        print(sum(bi * m for bi in b) - sum(gj for gj in g))

if __name__ == "__main__":
    solve()
"}

