            continue
        parts = line.strip().split()
        if len(parts) == 3:
            ops.append((int(parts[0]), int(parts[1]), int(parts[2])))

    # Track last operation for each row and column
    row_last = [(-1, 0) for _ in range(n + 1)]  # (timestamp, color)
    col_last = [(-1, 0) for _ in range(m + 1)]

    for op_num, op_type, idx, color in ops:
        if op_type == 1:
            # Row operation
            row_last[idx] = (op_num, color)
        else:
            # Column operation
            col_last[idx] = (op_num, color)

