from collections import defaultdict

def solve():
    a = input().strip()

    # Memo dictionary: key = (start, end), value = set of distinct strings
    memo = {}

    def count(start, end):
        if start > end:
            return {"")}
        if (start, end) in memo:
            return memo[(start, end)]

        # Try not merging the current character with the next one
        results = set()
        # We need to be careful: we can only merge adjacent pairs that sum to 9
        # So we need to consider where we can split
        for i in range(start, end):
            # Try to merge characters at positions i and i+1 if they sum to 9
            if i < end and int(a[i]) + int(a[i+1]) == 9:
                # Merge and recurse
                merged = '9' + count(start, i-1) + count(i+2, end)
                for s in merged:
                    results.add(s)
            else:
                # Don't merge, just add the current character
                left = count(start, i-1)
                right = count(i+1, end)
                for left_s in left:
                    for right_s in right:
                        results.add(left_s + a[i] + right_s)

        memo[(start, end)] = results
        return results

    # Get all distinct terminal states
    terminal_states = count(0, len(a) - 1)

    # Count how many have the maximum number of '9's
    if not terminal_states:
        print(1)
        return

    max_nines = max(s.count('9') for s in terminal_states)
    result = sum(1 for s in terminal_states if s.count('9') == max_nines)
    print(result)

