import sys

def is_connected(graph, n, start):
    visited = [False] * (n + 1)
    stack = [start]
    visited[start] = True

    while stack:
        u = stack.pop()
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)

    return all(visited)

def find_bridges(graph, n):
    visited = [False] * (n + 1)
    disc = [float('inf')] * (n + 1)
    low = [float('inf')] * (n + 1)
    time = [0]
    bridges = []

    def dfs(u, parent):
        visited[u] = True
        disc[u] = low[u] = time[0]
        time[0] += 1

        for v in graph[u]:
            if v == parent:
                continue

            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])

                # Bridge found
                if low[v] > disc[u]:
                    bridges.append((u, v))
            else:
                low[u] = min(low[u], disc[v])

    for u in range(1, n + 1):
        if not visited[u]:
            dfs(u, -1)

    return bridges

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    graph = [[] for _ in range(n + 1)]

    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        graph[x].append(y)
        graph[y].append(x)

    # Find all bridges
    bridges = find_bridges(graph, n)
    print(len(bridges))

if __name__ == "__main__":
    solve()
