import sys

def solve(p, k):
    """Find a polynomial f(x) with non-negative integer coefficients strictly less than k
    such that f(-k) = p. Return the coefficients or -1 if not possible."""

    coefficients = []
    current = p

    while current > 0:
        remainder = current % k
        coefficients.append(remainder)
        current = (current + remainder) // k

        # Optimization: if we've seen this remainder before and current is still > 0,
        # we might be in an infinite loop. Let's break if we see the same remainder again.
        if remainder == 0 and current == p:
            break

    # Check if all coefficients are less than k
    if all(0 <= c < k for c in coefficients):
        return coefficients
    else:
        return -1


