import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    p = float(data[1])
    t = int(data[2])

    # Dynamic programming: dp[i][j] = probability that after j seconds, exactly i people have entered
    dp = [[0.0 for _ in range(t + 2)] for _ in range(n + 2)]
    dp[0][0] = 1.0

    for j in range(t + 1):
        for i in range(n + 1):
            if dp[i][j] > 0:
                # Person i+1 might enter
                if i < n:
                    dp[i+1][j+1] += dp[i][j] * p
                # Person i+1 might not enter
                dp[i][j+1] += dp[i][j] * (1 - p)

    # Expected number of people on the escalator after t seconds is sum_{i=1}^n i * dp[i][t]
    expected = sum(i * dp[i][t] for i in range(1, n + 1))

    print(f"{expected:.12f}")

if __name__ == "__main__":
    solve()
