def solve():
    import sys
    input = sys.stdin.read().strip().split()
    if not input:
        return
    it = iter(input)
    n = int(next(it))
    k = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Find all primes up to 10^5
    primes = []
    is_prime = [True] * (100001)
    is_prime[0] = is_prime[1] = False
    for i in range(2, 100001):
        if is_prime[i]:
            primes.append(i)
            for j in range(i*i, 100001, i):
                is_prime[j] = False

    # Get all primes that appear in any number
    prime_set = set()
    for num in a:
        prime_factors = factorize(num, primes)
        prime_set.update(prime_factors.keys())

    # Build signatures
    from collections import defaultdict
    count = defaultdict(int)
    for num in a:
        sig = []
        prime_factors = factorize(num, primes)
        for p in sorted(prime_set):
            if p in prime_factors:
                sig.append(prime_factors[p] % k)
            else:
                sig.append(0)
