    # Count pairs
    result = 0
    seen = set()
    for sig in count:
        if sig in seen:
            continue
        seen.add(sig)
        comp = []
        for e in sig:
            comp.append((k - e) % k)
        comp_tuple = tuple(comp)

        if sig == comp_tuple:
