            for num in range(n + 1, 2 * n + 1):
                if bin(num).count('1') == k:
                    count += 1
            if count == m:
                result = n
                break

    if result == -1:
        # If still not found, search from power in both directions
        # Try larger ranges
        for power in power_of_two:
            for i in range(1, 10**6):
                n = power + i
                count = 0
                for num in range(n + 1, 2 * n + 1):
                    if bin(num).count('1') == k:
                        count += 1
                if count == m:
                    result = n
                    break

                n = power - i
                count = 0
                for num in range(n + 1, 2 * n + 1):
                    if bin(num).count('1') == k:
                        count += 1
                if count == m:
                    result = n
                    break

