def count_numbers_with_k_ones_in_range(start, end, k):
    count = 0
    for num in range(start, end + 1):
        # Use bitwise to count ones for efficiency
        t = bin(num).count('1')
        if t == k:
            count += 1
    return count

def solve(m, k):
    # Try powers of 2 first
    power_of_two = [1 << b for b in range(1, 65)]
    result = -1
    n_candidates = set()
    n_candidates.update(power_of_two)

    # Add nearby candidates (values around powers of 2)
    for p in power_of_two:
        for i in range(1, 100):
            n_candidates.add(p + i)
            n_candidates.add(p - i)

    # Also try values from 1 to some reasonable upper bound
    # for cases that don't match the power pattern
    # We'll use this for initial quick check
    initial_upper = 10**5
    for n in range(1, initial_upper):
        n_candidates.add(n)

    # Find the first candidate that works
    for n in n_candidates:
        start = n + 1
        end = 2 * n
        count = count_numbers_with_k_ones_in_range(start, end, k)

        if count == m:
            return n

    # If not found, do a broader search
    # Try powers of two with even larger nearby values
    result = -1
    for power in power_of_two:
        for i in range(1, 5000000):
            n = power + i
            if n > 2 * 10**18:
                break
            count = 0
            for num in range(n + 1, 2 * n + 1):
                t = bin(num).count('1')
                if t == k:
                    count += 1
            if count == m:
                return n

        for i in range(1, 5000000):
            n = power - i
            if n < 1:
                break
            count = 0
            for num in range(n + 1, 2 * n + 1):
                t = bin(num).count('1')
                if t == k:
                    count += 1
            if count == m:
                return n

    return 0

# Entry point
