import sys

def solve():
    s, x = map(int, sys.stdin.readline().split())

    # Check if (s - x) is negative or odd
    if (s - x) < 0 or (s - x) % 2 != 0:
        print(0)
        return

    y = (s - x) // 2

    # Check if x & y != 0
    if (x & y) != 0:
        print(0)
        return

    # Count the number of bits set in x
    k = bin(x).count('1')

    # The number of solutions is 2^k if y != 0, but only 2 if y == 0
    if y == 0:
        print(2)
    else:
        print(1 << k)

if __name__ == "__main__":
    solve()
"}

